// @DEV-GUIDE: Ability function tags (Position Templates spec, step 4). The
// dataset ships as resources/data/ability_tags.json, generated by
// ../ad_data_gather_script/build_ability_tags.py (dotaconstants mechanical layer
// + Liquipedia CC lists + LLM judgment pass + tag_overrides.json) and curated by
// hand via its review_flags.json. This module owns the CLOSED vocabulary (the
// build script's VOCAB must match) and the pure parsing/validation used by the
// main-process loader. Tags power the build-needs engine and the reason chips —
// role RANKING is primarily the shifts-derived greed axis (role-scoring.ts);
// tags deliberately carry only small static weights to avoid double-counting.
// Round-4 tags (good_shard / good_aghanims / skill_point_sink) are NOT needs-
// engine inputs: they drive role-INDEPENDENT own-pick verdicts in
// scan-processor (Aghanim's stacking boost, skill-point-sink damp) and the
// opt-in overlay markers — they apply with role mode off too.
// Distinct from tags, an entry may carry `roleMust: [positions]` — a hand-
// curated VERDICT (not a mechanical fact, so deliberately outside the tag
// vocabulary): "recommend this for these positions even if stats disagree".
// Reserved for abilities whose value the stats systematically miss (e.g.
// Glimpse for supports); it guarantees a top-tier slot when the user's active
// role matches (top-tier.ts) on top of a role-layer boost (role-scoring.ts).
// Round 5 (docs/proposals/community-tags-round5.md) adds three MECHANICAL tags
// derived by the build script from dotaconstants (never voted on, hidden from
// the Tag Lab composer — MECHANICAL_TAGS) and three entry fields beside
// `requires`: `combos` (curated deny partners), `viaUpgrade` (a tag granted by
// Shard/Scepter — counted at full value, tooltip says so) and `with` (a tag
// that holds only while the same player has drafted a listed ability).

export const TAG_VOCABULARY = [
  'hard_cc',
  'soft_cc',
  'setup_cc',
  'aoe',
  'nuke',
  'waveclear',
  'farm_tool',
  'steroid',
  'sustain_self',
  'save_ally',
  'team_aura',
  'mobility',
  'initiation',
  'summon',
  'teamfight_ult',
  'passive_value',
  'melee_only',
  'ranged_only',
  'grants_ranged',
  'good_with_rearm',
  'mana_hungry',
  'channeled',
  // Round 4 (Tag Lab): item-upgrade quality + skill-point competition
  'good_shard',
  'good_aghanims',
  'skill_point_sink',
  // Round 5 mechanical layer (dotaconstants `dispellable` / `bkbpierce`):
  // the DEMAND side of dispels and the target side of counters. Built by the
  // script, not curated; an override may still remove a wrong one.
  'debuff_dispellable',
  'debuff_strong_only',
  'bkb_piercing',
  // Round 5 step 2: the reposition split (community move_enemy) and the
  // dispel split (community dispel). knockback is descriptive only in v1.
  'reposition_enemy',
  'reposition_ally',
  'knockback',
  'dispel_self',
  'dispel_ally',
  'purge_enemy',
  // Round 5 step 3: the damage-amp split (community damage_amp). spell_steroid
  // is SELF spell amp (the caster's steroid); the amp_* three are enemy
  // debuffs the whole team benefits from, split by damage type.
  'spell_steroid',
  'amp_physical',
  'amp_magical',
  'amp_all',
  // Round 5 step 4: "playable on its own, so denying it is not a dead pick"
  // (community good_counter). The combo links live in the entry's `combos`.
  'good_deny',
  // Round 5 step 5: the community's "never leave it to the enemy" verdict.
  // VISUAL ONLY (border + tooltip with the live numbers) — never a score
  // term: the stat score already ranks its carriers top-8 of 513, and the
  // build script audits carriers whose live stats stop agreeing.
  'pick_asap',
] as const

export type AbilityTag = (typeof TAG_VOCABULARY)[number]

/** Tags the build script derives mechanically; hidden from the Tag Lab
 * composer and from reason chips (they describe what OTHER abilities do to
 * you, not what a candidate offers). */
export const MECHANICAL_TAGS: ReadonlySet<AbilityTag> = new Set<AbilityTag>([
  'debuff_dispellable',
  'debuff_strong_only',
  'bkb_piercing',
])

/** Item upgrade that grants a `viaUpgrade` tag. */
export type UpgradeKind = 'shard' | 'scepter'

const VOCAB_SET: ReadonlySet<string> = new Set(TAG_VOCABULARY)

// Hero-MODEL tag vocabulary (model-pairing Layer B) — the build script's
// HERO_VOCAB must match. Talent-profile tags are auto-derived from GENERIC
// talents only (ability-specific talents are dead on an AD model); innate_*
// tags are judgment, curated via hero_tag_overrides.json / the Tag Lab.
export const HERO_TAG_VOCABULARY = [
  'rc_talents',
  'caster_talents',
  'tank_talents',
  'utility_talents',
  'innate_offense',
  'innate_tank',
  'innate_team',
] as const

export type HeroTag = (typeof HERO_TAG_VOCABULARY)[number]

const HERO_VOCAB_SET: ReadonlySet<string> = new Set(HERO_TAG_VOCABULARY)

export type HeroAttackType = 'Melee' | 'Ranged'
export type HeroPrimaryAttr = 'str' | 'agi' | 'int' | 'all'

/** Hero-model metadata (hero_meta.json): attributes for role-fit scoring plus
 * chassis fields (model-pairing Layer A) — the body properties stat gains
 * cannot see. All optional: missing data scores as a neutral percentile. */
export interface HeroMeta {
  attackType?: HeroAttackType
  primaryAttr?: HeroPrimaryAttr
  baseStr?: number
  baseAgi?: number
  baseInt?: number
  strGain?: number
  agiGain?: number
  intGain?: number
  attackRange?: number
  /** BAT (base attack time) — LOWER is better. */
  attackRate?: number
  projectileSpeed?: number
  moveSpeed?: number
  baseArmor?: number
  baseHealth?: number
  baseMana?: number
  baseAttackMin?: number
  baseAttackMax?: number
  /** Hero-model tags (Layer B): talent profile + innate value. */
  tags?: ReadonlySet<HeroTag>
  /** Curated must-pick positions for the MODEL (mirrors ability roleMust). */
  roleMust?: ReadonlySet<RoleMustPosition>
  /** Curated never-recommend positions for the MODEL (Drow/Luna for supports:
   * a premier core body should not be stolen from your cores). LIFTED once
   * every teammate has picked a model — then taking it only denies enemies. */
  roleAvoid?: ReadonlySet<RoleMustPosition>
}

/** Draft position (1-5). Structurally identical to role-scoring's
 * DraftPosition — declared here too so this module stays import-free of the
 * scoring layer. */
export type RoleMustPosition = 1 | 2 | 3 | 4 | 5

/** Injected into the scan processor; absent dep = tags feature off (no-op). */
export interface AbilityTagsLookup {
  /** Tags for an ability internal name; undefined when untagged/unknown. */
  getTags(abilityName: string): ReadonlySet<AbilityTag> | undefined
  /** Curated must-pick positions for an ability; undefined when not curated. */
  getRoleMust(abilityName: string): ReadonlySet<RoleMustPosition> | undefined
  /** Curated never-recommend positions (roleAvoid); all five = never suggest
   * at all, role mode on or off (blatantly bad picks, e.g. Ransack). */
  getRoleAvoid(abilityName: string): ReadonlySet<RoleMustPosition> | undefined
  /** Dependency gate: entries are ability internal names, 'model:<hero>', or
   * 'tag:<tag>'. The ability is only ever SUGGESTED when at least one entry
   * is satisfied (Eclipse -> Lucent Beam; Requiem -> the SF model whose
   * innate feeds it; Rearm -> a good_with_rearm ability drafted or still in
   * the pool — the enabler goes first, so pool presence counts). */
  getRequires(abilityName: string): readonly string[] | undefined
  /** Curated deny partners (round 5): ability internal names or 'model:<hero>'.
   * Directional — the candidate lists what the ENEMY must hold for taking the
   * candidate to be a worthwhile deny. Optional: older lookups/stubs omit it. */
  getCombos?(abilityName: string): readonly string[] | undefined
  /** Tags the ability only has through an item upgrade (round 5). Counted at
   * full value; the tooltip names the upgrade. */
  getViaUpgrade?(abilityName: string): ReadonlyMap<AbilityTag, UpgradeKind> | undefined
  /** Conditional tags (round 5): the tag holds only while the SAME player has
   * drafted one of the listed abilities (Nether Strike's knockback needs
   * Greater Bash). */
  getWith?(abilityName: string): ReadonlyMap<AbilityTag, readonly string[]> | undefined
  /** Attack type of a hero internal name (hero_meta.json); undefined when unknown. */
  getHeroAttackType(heroName: string): HeroAttackType | undefined
  /** Full hero metadata (attributes/gains) for model role-fit; undefined when unknown. */
  getHeroMeta(heroName: string): HeroMeta | undefined
}

/**
 * Parse + validate the ability_tags.json dataset. Unknown tags are DROPPED
 * (with their names reported) rather than failing the load — a newer dataset
 * must never brick an older app. Returns null for structurally invalid input.
 */
export function parseAbilityTagsDataset(json: unknown): {
  tagsByAbility: Map<string, ReadonlySet<AbilityTag>>
  roleMustByAbility: Map<string, ReadonlySet<RoleMustPosition>>
  roleAvoidByAbility: Map<string, ReadonlySet<RoleMustPosition>>
  requiresByAbility: Map<string, readonly string[]>
  combosByAbility: Map<string, readonly string[]>
  viaUpgradeByAbility: Map<string, ReadonlyMap<AbilityTag, UpgradeKind>>
  withByAbility: Map<string, ReadonlyMap<AbilityTag, readonly string[]>>
  droppedTags: string[]
} | null {
  if (typeof json !== 'object' || json === null) return null
  const abilities = (json as { abilities?: unknown }).abilities
  if (typeof abilities !== 'object' || abilities === null) return null

  const tagsByAbility = new Map<string, ReadonlySet<AbilityTag>>()
  const roleMustByAbility = new Map<string, ReadonlySet<RoleMustPosition>>()
  const roleAvoidByAbility = new Map<string, ReadonlySet<RoleMustPosition>>()
  const requiresByAbility = new Map<string, readonly string[]>()
  const combosByAbility = new Map<string, readonly string[]>()
  const viaUpgradeByAbility = new Map<string, ReadonlyMap<AbilityTag, UpgradeKind>>()
  const withByAbility = new Map<string, ReadonlyMap<AbilityTag, readonly string[]>>()
  const dropped = new Set<string>()
  /** Non-empty, deduped strings; null when the field is not a list. */
  const parseNames = (raw: unknown): string[] | null =>
    Array.isArray(raw)
      ? [...new Set(raw.filter((r): r is string => typeof r === 'string' && r.length > 0))]
      : null
  const parsePositions = (raw: unknown): Set<RoleMustPosition> | null => {
    if (!Array.isArray(raw)) return null
    const positions = new Set<RoleMustPosition>()
    for (const pos of raw) {
      if (typeof pos === 'number' && Number.isInteger(pos) && pos >= 1 && pos <= 5) {
        positions.add(pos as RoleMustPosition)
      }
    }
    return positions
  }
  for (const [name, entry] of Object.entries(abilities)) {
    const rawTags = (entry as { tags?: unknown })?.tags
    if (!Array.isArray(rawTags)) continue
    const tags = new Set<AbilityTag>()
    for (const tag of rawTags) {
      if (typeof tag === 'string' && VOCAB_SET.has(tag)) {
        tags.add(tag as AbilityTag)
      } else if (typeof tag === 'string') {
        dropped.add(tag)
      }
    }
    tagsByAbility.set(name, tags)

    // Curated must-pick / never-recommend positions: invalid values are
    // dropped silently (a newer dataset must never brick an older app),
    // empty sets are omitted.
    const must = parsePositions((entry as { roleMust?: unknown })?.roleMust)
    if (must !== null && must.size > 0) roleMustByAbility.set(name, must)
    const avoid = parsePositions((entry as { roleAvoid?: unknown })?.roleAvoid)
    if (avoid !== null && avoid.size > 0) roleAvoidByAbility.set(name, avoid)

    // Dependency gates: non-empty strings only, deduped; empty lists omitted.
    const reqs = parseNames((entry as { requires?: unknown })?.requires)
    if (reqs !== null && reqs.length > 0) requiresByAbility.set(name, reqs)

    // Deny partners (round 5): same shape as requires, same validation.
    const combos = parseNames((entry as { combos?: unknown })?.combos)
    if (combos !== null && combos.length > 0) combosByAbility.set(name, combos)

    // Upgrade-granted tags: {tag: 'shard' | 'scepter'}. The tag must be in the
    // vocabulary AND on the entry's tag list (the field only annotates how the
    // tag is obtained); anything else is dropped silently.
    const rawVia = (entry as { viaUpgrade?: unknown })?.viaUpgrade
    if (typeof rawVia === 'object' && rawVia !== null && !Array.isArray(rawVia)) {
      const via = new Map<AbilityTag, UpgradeKind>()
      for (const [tag, kind] of Object.entries(rawVia)) {
        if (tags.has(tag as AbilityTag) && (kind === 'shard' || kind === 'scepter')) {
          via.set(tag as AbilityTag, kind)
        }
      }
      if (via.size > 0) viaUpgradeByAbility.set(name, via)
    }

    // Conditional tags: {tag: [ability names]} — tag must be on the entry's
    // list, the dependency list non-empty after validation.
    const rawWith = (entry as { with?: unknown })?.with
    if (typeof rawWith === 'object' && rawWith !== null && !Array.isArray(rawWith)) {
      const cond = new Map<AbilityTag, readonly string[]>()
      for (const [tag, deps] of Object.entries(rawWith)) {
        const names = parseNames(deps)
        if (tags.has(tag as AbilityTag) && names !== null && names.length > 0) {
          cond.set(tag as AbilityTag, names)
        }
      }
      if (cond.size > 0) withByAbility.set(name, cond)
    }
  }
  return {
    tagsByAbility,
    roleMustByAbility,
    roleAvoidByAbility,
    requiresByAbility,
    combosByAbility,
    viaUpgradeByAbility,
    withByAbility,
    droppedTags: [...dropped],
  }
}

/** Parse + validate hero_meta.json. Missing/invalid stat fields become
 * undefined (model fit then treats them as neutral) — never fatal. */
export function parseHeroMeta(json: unknown): Map<string, HeroMeta> | null {
  if (typeof json !== 'object' || json === null) return null
  const num = (v: unknown): number | undefined =>
    typeof v === 'number' && Number.isFinite(v) ? v : undefined
  const result = new Map<string, HeroMeta>()
  for (const [name, entry] of Object.entries(json)) {
    if (typeof entry !== 'object' || entry === null) continue
    const e = entry as Record<string, unknown>
    const meta: HeroMeta = {
      attackType:
        e.attackType === 'Melee' || e.attackType === 'Ranged'
          ? e.attackType
          : undefined,
      primaryAttr:
        e.primaryAttr === 'str' ||
        e.primaryAttr === 'agi' ||
        e.primaryAttr === 'int' ||
        e.primaryAttr === 'all'
          ? e.primaryAttr
          : undefined,
      baseStr: num(e.baseStr),
      baseAgi: num(e.baseAgi),
      baseInt: num(e.baseInt),
      strGain: num(e.strGain),
      agiGain: num(e.agiGain),
      intGain: num(e.intGain),
      attackRange: num(e.attackRange),
      attackRate: num(e.attackRate),
      projectileSpeed: num(e.projectileSpeed),
      moveSpeed: num(e.moveSpeed),
      baseArmor: num(e.baseArmor),
      baseHealth: num(e.baseHealth),
      baseMana: num(e.baseMana),
      baseAttackMin: num(e.baseAttackMin),
      baseAttackMax: num(e.baseAttackMax),
    }
    // Hero tags: unknown values dropped silently (newer dataset, older app);
    // roleMust validated to positions 1-5 like the ability variant.
    if (Array.isArray(e.tags)) {
      const heroTags = new Set<HeroTag>()
      for (const t of e.tags) {
        if (typeof t === 'string' && HERO_VOCAB_SET.has(t)) heroTags.add(t as HeroTag)
      }
      if (heroTags.size > 0) meta.tags = heroTags
    }
    const parseHeroPositions = (raw: unknown): Set<RoleMustPosition> | null => {
      if (!Array.isArray(raw)) return null
      const positions = new Set<RoleMustPosition>()
      for (const p of raw) {
        if (typeof p === 'number' && Number.isInteger(p) && p >= 1 && p <= 5) {
          positions.add(p as RoleMustPosition)
        }
      }
      return positions
    }
    const heroMust = parseHeroPositions(e.roleMust)
    if (heroMust !== null && heroMust.size > 0) meta.roleMust = heroMust
    const heroAvoid = parseHeroPositions(e.roleAvoid)
    if (heroAvoid !== null && heroAvoid.size > 0) meta.roleAvoid = heroAvoid
    result.set(name, meta)
  }
  return result
}

/** Context that can WAIVE the inert filter for a candidate. */
export interface InertExceptions {
  /** The candidate is native to the selected model's hero (Wukong's Command on
   * the Monkey King model): the game designed them together — never inert. */
  nativeToModel?: boolean
  /** One of the user's DRAFTED abilities is tagged grants_ranged (Psi Blades,
   * Take Aim): ranged_only candidates work on a melee model again. */
  picksGrantRanged?: boolean
}

/**
 * True when an ability is mechanically inert or crippled on the given hero
 * model's attack type (cleave on a ranged model, projectile mechanics on a
 * melee one). Used as a HARD top-tier exclusion, not a score tweak.
 * Exceptions (user ruling 2026-08-30, Wukong's Command case): the candidate's
 * own native model is always exempt, and a drafted grants_ranged ability
 * waives ranged_only on melee models (melee_only on ranged models has no
 * symmetric waiver — nothing grants melee).
 */
export function isInertOnModel(
  tags: ReadonlySet<AbilityTag> | undefined,
  attackType: HeroAttackType | undefined,
  exceptions?: InertExceptions,
): boolean {
  if (tags === undefined || attackType === undefined) return false
  if (exceptions?.nativeToModel === true) return false
  if (attackType === 'Ranged' && tags.has('melee_only')) return true
  if (attackType === 'Melee' && tags.has('ranged_only')) {
    return exceptions?.picksGrantRanged !== true
  }
  return false
}
